#!/usr/bin/env bash
# test-session-restart.sh — session-restart.sh restarts ONE idle crss Claude session: it pins the running
# sessionId, types /exit, and waits for the start script's supervisor loop to relaunch `--resume <sid>`.
#
# tmux and claude are stubbed (every stub lives in the fake HOME's bin dir, first on PATH). The supervisor
# loop is the REAL loop generated by new-session.sh, extracted from the generated start script and run as a
# "pane" under setsid with shortened sleeps, the same technique as test-session-resume.sh case 9.
set -uo pipefail
HERE="$(cd "$(dirname "$0")" && pwd)"
source "$HERE/lib.sh"
RS="$HERE/../scripts/session-restart.sh"
NS="$HERE/../scripts/new-session.sh"

T="$(mktemp -d)"
# Everything the cleanup trap reads is set before the trap is installed.
NH="$T/home"; STATE="$T/state"; RUNS="$T/runs"; B="$NH/.local/bin"
S="" R="" SC="" RUN="" PANEF="" PANE="" PSID="" OLD="" SID="" PIN="" OUT="" RC=0 MARK=0 MNAME="" MASTER=""
cleanup() {
  if [ -n "$T" ] && [ -f "$T/state/all.sids" ]; then
    while read -r sid; do [ -n "$sid" ] && pkill -s "$sid" 2>/dev/null; done < "$T/state/all.sids"
  fi
  [ -n "$T" ] && pkill -f -- "$T/" 2>/dev/null
  [ -n "$T" ] && rm -rf "$T"
}
trap cleanup EXIT

# ── fake HOME, stub dir, stubs (#!/bin/bash: a /usr/bin/env shebang would make the fake claude's comm "bash") ──
mkdir -p "$B" "$NH/.claude/sessions" "$NH/.sessions/resume" "$NH/.sessions/rstm" "$STATE" "$RUNS" "$T/no-overlay" "$T/units"
touch "$STATE/tmux.log" "$STATE/all.sids"

cat > "$B/claude" <<'EOF'
#!/bin/bash
# Fake claude. --version prints the version file. A launch registers itself like the real CLI (sessionId from
# --resume, else the fresh sid), optionally starts a child process, then idles until its exit-<pid> file exists.
if [ "${1:-}" = --version ]; then echo "$(cat "$STUB_STATE/version") (Claude Code)"; exit 0; fi
# rc-override: re-exec once with the --remote-control value replaced (the relaunch carries a different name).
if [ -f "$STUB_STATE/rc-override" ]; then
  newrc="$(cat "$STUB_STATE/rc-override")"; rm -f "$STUB_STATE/rc-override"
  rargs=(); skip=0
  for a in "$@"; do
    if [ "$skip" = 1 ]; then rargs+=("$newrc"); skip=0; continue; fi
    rargs+=("$a"); [ "$a" = --remote-control ] && skip=1
  done
  exec "$0" "${rargs[@]}"
fi
sid=""; prev=""
for a in "$@"; do [ "$prev" = --resume ] && sid="$a"; prev="$a"; done
[ -n "$sid" ] || sid="$(cat "$STUB_STATE/fresh-sid")"
[ -f "$STUB_STATE/sid-override" ] && sid="$(cat "$STUB_STATE/sid-override")"
ver="$(cat "$STUB_STATE/version")"
[ -f "$STUB_STATE/version-override" ] && ver="$(cat "$STUB_STATE/version-override")"
st=idle
[ -f "$STUB_STATE/status" ] && st="$(cat "$STUB_STATE/status")"
me=$$
printf '%s\n' "$*" >> "$STUB_STATE/launches"
printf '{"pid": %s, "sessionId": "%s", "version": "%s", "status": "%s"}\n' "$me" "$sid" "$ver" "$st" > "$HOME/.claude/sessions/$me.json"
if [ -f "$STUB_STATE/child" ]; then bash -c "$(cat "$STUB_STATE/child")" & fi
fifo="$STUB_STATE/fifo-$me"
mkfifo "$fifo"; exec 9<>"$fifo"
end=$((SECONDS + 60))
while [ ! -e "$STUB_STATE/exit-$me" ] && [ "$SECONDS" -lt "$end" ]; do read -r -t 0.2 -u 9 _; done
rm -f "$HOME/.claude/sessions/$me.json" "$fifo"
exit 0
EOF

cat > "$B/tmux" <<'EOF'
#!/bin/bash
# Fake tmux: logs every call and answers only what session-restart and the supervisor loop use.
# Pane state per session lives in $STUB_STATE/<session>.<part>.
echo "$*" >> "$STUB_STATE/tmux.log"
cmd="${1:-}"; shift || true
target=""; rest=()
while [ $# -gt 0 ]; do
  if [ "$1" = -t ]; then target="${2:-}"; shift; shift || true; else rest+=("$1"); shift; fi
done
s="${target#=}"; s="${s%:}"
f() { printf '%s/%s.%s' "$STUB_STATE" "$s" "$1"; }
case "$cmd" in
  has-session)
    [ -f "$(f panepid)" ] ;;
  display-message|display)
    [ -f "$(f panepid)" ] && cat "$(f panepid)" ;;
  capture-pane)
    e=0
    for a in "${rest[@]+"${rest[@]}"}"; do [ "$a" = -e ] && e=1; done
    src="$(f pane)"
    if [ "$e" = 1 ] && [ -f "$(f pane-e)" ]; then src="$(f pane-e)"; fi
    INP="$(cat "$(f input)" 2>/dev/null)" awk '/❯/ { print $0 ENVIRON["INP"]; next } { print }' "$src"
    if [ -f "$(f dialog)" ]; then printf '%s\n' "Exit and stop tasks" "Move to background" "Stay"; fi ;;
  send-keys)
    if [ "${rest[0]:-}" = -l ]; then
      printf '%s%s' "$(cat "$(f input)" 2>/dev/null)" "${rest[1]:-}" > "$(f input)"
    else
      for k in "${rest[@]+"${rest[@]}"}"; do
        case "$k" in
          BSpace) cur="$(cat "$(f input)" 2>/dev/null)"; printf '%s' "${cur%?}" > "$(f input)" ;;
          Escape) rm -f "$(f dialog)"; echo escape >> "$(f events)" ;;
          Enter)
            cur="$(cat "$(f input)" 2>/dev/null)"
            : > "$(f input)"
            if [ "$cur" = /exit ]; then
              if [ -f "$(f tasks)" ]; then
                touch "$(f dialog)"
              elif [ ! -f "$(f stuck)" ]; then
                cpid="$(pgrep -P "$(cat "$(f panepid)")" -x claude | head -1)"
                [ -n "$cpid" ] && touch "$STUB_STATE/exit-$cpid"
              fi
            elif [ -n "$cur" ]; then
              echo "submitted:$cur" >> "$(f events)"
            fi ;;
        esac
      done
    fi ;;
  *) : ;;
esac
EOF

cat > "$B/session-send" <<'EOF'
#!/bin/bash
# Fake session-send: logs its args and the --file body, exits with $STUB_STATE/send-rc (default 0).
echo "$*" >> "$STUB_STATE/session-send.log"
f=""; prev=""
for a in "$@"; do [ "$prev" = --file ] && f="$a"; prev="$a"; done
[ -n "$f" ] && cat "$f" >> "$STUB_STATE/session-send.log"
exit "$(cat "$STUB_STATE/send-rc" 2>/dev/null || echo 0)"
EOF

printf '#!/bin/bash\nexit 0\n' > "$B/systemctl"
chmod +x "$B/claude" "$B/tmux" "$B/session-send" "$B/systemctl"
ln -sf "$HERE/../scripts/session-alias.sh" "$B/session-alias"

export HOME="$NH" PATH="$B:$PATH" STUB_STATE="$STATE"
# Guard: the stubs must be what the script's bare `tmux` and `session-send` resolve to. Never the real tmux.
if [ "$(command -v tmux)" != "$B/tmux" ] || [ "$(command -v session-send)" != "$B/session-send" ]; then
  echo "FAIL: tmux/session-send do not resolve to the stubs in $B (tmux=$(command -v tmux))"
  exit 1
fi

# ── master start script: REAL, generated by new-session.sh into the fake HOME ───────────────────────────
env -u XDG_CONFIG_HOME -u XDG_DATA_HOME -u XDG_STATE_HOME -u CRSS_UNIT_DIR -u CRSS_SESSIONS_DIR \
  -u CRSS_CLAUDE_HOME -u CRSS_BIN_DIR -u CRSS_AUTONOMOUS \
  HOME="$NH" PATH="$PATH" SESSION_ALIAS_STORE="$T/alias-store" CRSS_HOME="$T/no-overlay" \
  CRSS_SESSION_PREFIX=px CRSS_CLAUDE_BIN="$B/claude" \
  bash "$NS" rstm sessions --alias rstm </dev/null >/dev/null 2>&1
set -- "$B"/px-rstm-*-start.sh
if [ ! -f "$1" ]; then echo "FAIL: new-session did not generate a start script"; exit 1; fi
MASTER="$T/master-start.sh"
MNAME="$(basename "$1" -start.sh)"
mv "$1" "$MASTER"
: > "$STATE/tmux.log"   # setup calls are not the restart's; the target check reads only what follows

# Restart-under-test environment. CRSS_RESTART_* waits are tiny; MIN_AGE is 0 except in the age case.
export CRSS_HOME="$T/no-overlay" CRSS_SESSION_PREFIX=px CRSS_LEGACY_PREFIXES="" CRSS_AUTONOMOUS=0
export CRSS_CLAUDE_HOME="$NH/.claude" CRSS_UNIT_DIR="$T/units" CRSS_BIN_DIR="$B"
export CRSS_RESTART_POLL=0.2 CRSS_RESTART_WAIT=15 CRSS_RESTART_EXIT_GRACE=4 CRSS_RESTART_MIN_AGE=0
export CRSS_RESTART_TYPE_SETTLE=0.2 CRSS_RESTART_NUDGE_DELAY=0
unset CRSS_PROTECT_NAMES CRSS_RESTART_CHILD_ALLOW

PY_EXTRACT='import re, shlex, sys
s = open(sys.argv[1]).read()
m = re.search(r"tmux send-keys -t \"[^\"]+\" (\x27LOG_FILE=.*?\ndone\x27)", s, re.S)
print(shlex.split(m.group(1))[0])'

# ── helpers ───────────────────────────────────────────────────────────────────────────────────────────
uuid() { printf '%08x-%04x-4%03x-8%03x-%012x\n' $((RANDOM * RANDOM)) $RANDOM $((RANDOM % 4096)) $((RANDOM % 4096)) $((RANDOM * RANDOM * RANDOM)); }
pin_now() { if [ -e "$PIN" ]; then head -1 "$PIN"; else echo "<absent>"; fi; }
mark_log() { MARK="$(wc -l < "$STATE/tmux.log")"; MARK="${MARK// /}"; }
sent_since() { tail -n +"$((MARK + 1))" "$STATE/tmux.log" | grep -c send-keys; }
submitted_count() { local n; n="$(grep -c submitted "$STATE/$S.events" 2>/dev/null)"; echo "${n:-0}"; }
reg_field() { python3 -c 'import json, sys; print(json.load(open(sys.argv[1]))[sys.argv[2]])' "$NH/.claude/sessions/$1.json" "$2" 2>/dev/null; }

# reset_globals: state shared by every session; each case starts from it.
reset_globals() {
  rm -f "$STATE/child" "$STATE/status" "$STATE/version-override" "$STATE/sid-override" "$STATE/rc-override" "$STATE/send-rc" \
        "$STATE/session-send.log" "$STATE/launches"
  echo 1.0.0 > "$STATE/version"
  uuid > "$STATE/fresh-sid"
}

# new_script TAG: the master start script, renamed to px-rst<TAG>-<pid>, written into the stub bin dir.
new_script() {
  S="px_rst$1-$$"; R="px-rst$1-$$"; SC="$B/$R-start.sh"
  sed -e "s/$MNAME/$R/g" -e "s/${MNAME/px-/px_}/$S/g" "$MASTER" > "$SC"
  chmod +x "$SC"
  PIN="$NH/.sessions/resume/$R.uuid"
}

# pane_with STATUS ABOVE FOOTER: the plain pane. ABOVE is a line right above the prompt box ("" for none).
pane_with() {
  {
    echo "● ran 1 shell command, press esc to interrupt next time"
    echo "$1"
    [ -n "$2" ] && echo "$2"
    echo "────────────────"
    echo "❯ "
    echo "────────────────"
    echo "$3"
  } > "$STATE/$S.pane"
  rm -f "$STATE/$S.pane-e"
}
IDLE_FOOT="  ⏵⏵ bypass permissions on (shift+tab to cycle) · ← 3 agents"
idle_pane() { pane_with "✻ Cooked for 2s · done 6:08 PM" "" "$IDLE_FOOT"; }
# pane_e_prompt RAW: the same pane with the prompt line replaced by RAW (escape bytes allowed) for capture -e.
pane_e_prompt() { sed -e "s|^❯ \$|$1|" "$STATE/$S.pane" > "$STATE/$S.pane-e"; }

# start_session TAG [SED_EXPR]: a live pane running the real loop (on a shortened copy of it), with the old
# claude registered. SED_EXPR edits only the running payload copy. Sets S R SC PIN PANE OLD SID.
start_session() {
  local extra="${2:-}" pl
  new_script "$1"
  RUN="$RUNS/$S"; mkdir -p "$RUN"; : > "$RUN/.sessions-init-$R"   # sentinel: the first launch is --continue
  PANEF="$STATE/$S.panepid"
  idle_pane
  pl="$(python3 -c "$PY_EXTRACT" "$SC")"
  pl="$(printf '%s\n' "$pl" | sed -e 's/sleep 300/sleep 0.2/' -e 's/sleep 10$/sleep 0.2/')"
  if [ -n "$extra" ]; then pl="$(printf '%s\n' "$pl" | sed -e "$extra")"; fi
  rm -f "$PANEF"
  ( cd "$RUN" && exec setsid bash -c 'echo $$ > "$1"; shift; eval "$1"' _ "$PANEF" "$pl" ) </dev/null >/dev/null 2>&1 &
  for _ in $(seq 1 50); do [ -s "$PANEF" ] && break; sleep 0.1; done
  PANE="$(cat "$PANEF" 2>/dev/null)"
  PSID="$(ps -o sid= -p "$PANE" 2>/dev/null | tr -d ' ')"
  [ -n "$PSID" ] && echo "$PSID" >> "$STATE/all.sids"
  OLD=""
  for _ in $(seq 1 60); do
    OLD="$(pgrep -P "$PANE" -x claude 2>/dev/null | head -1)"
    [ -n "$OLD" ] && [ -s "$NH/.claude/sessions/$OLD.json" ] && break
    sleep 0.1
  done
  SID="$(cat "$STATE/fresh-sid")"
  if [ -f "$STATE/child" ]; then
    for _ in $(seq 1 30); do pgrep -P "$OLD" >/dev/null 2>&1 && break; sleep 0.1; done
  fi
}

# end_session: kill the pane's whole session and drop everything this case made.
end_session() {
  [ -n "$PSID" ] && pkill -s "$PSID" 2>/dev/null
  PSID=""
  if [ -n "$S" ]; then rm -f "$STATE/$S".* ; fi
  [ -n "$SC" ] && rm -f "$SC"
  [ -n "$PIN" ] && rm -f "$PIN"
  rm -f "$NH/.claude/sessions/"*.json
}

# refused LABEL WORD DETAIL [ENV=VAL...]: restart must refuse with exit 1 and nothing sent or written.
refused() {
  local label="$1" word="$2" detail="$3" pinb sum
  shift 3
  pinb="$(pin_now)"; sum="$(cksum < "$SC")"; mark_log
  OUT="$(env "$@" bash "$RS" "$S" 2>&1)"; RC=$?
  ok "$label-exit1" "$RC" 1
  has "$label-status" "$OUT" "session-restart: $S: REFUSED($word)"
  if [ -n "$detail" ]; then has "$label-detail" "$OUT" "$detail"; fi
  ok "$label-no-keys" "$(sent_since)" 0
  ok "$label-pin-unchanged" "$(pin_now)" "$pinb"
  ok "$label-script-unchanged" "$(cksum < "$SC")" "$sum"
  ok "$label-no-submit" "$(submitted_count)" 0
}

# dry_ok LABEL [ENV=VAL...]: --dry-run prints DRY-RUN, exits 0, and sends nothing.
dry_ok() {
  local label="$1"
  shift
  mark_log
  OUT="$(env "$@" bash "$RS" "$S" --dry-run 2>&1)"; RC=$?
  ok "$label-exit0" "$RC" 0
  has "$label-dry-run" "$OUT" "DRY-RUN"
  ok "$label-no-keys" "$(sent_since)" 0
}

# ── 1. happy path ───────────────────────────────────────────────────────────────────────────────────
echo "== happy path"
reset_globals
start_session h1
echo 2.0.0 > "$STATE/version"
mark_log
OUT="$(bash "$RS" "$S" 2>&1)"; RC=$?
ok "happy-exit0" "$RC" 0
has "happy-ok-line" "$OUT" "session-restart: $S: OK pid $OLD -> "
has "happy-version" "$OUT" "version 2.0.0"
has "happy-sid" "$OUT" "sessionId $SID"
has "happy-rc" "$OUT" "remote-control $R "
NEWPID="$(sed -n 's/.*OK pid [0-9]* -> \([0-9]*\) .*/\1/p' <<<"$OUT")"
ok "happy-new-pid-differs" "$([ -n "$NEWPID" ] && [ "$NEWPID" != "$OLD" ] && echo yes || echo no)" yes
ok "happy-pin-holds-old-sid" "$(pin_now)" "$SID"
ok "happy-new-registry-sid" "$(reg_field "$NEWPID" sessionId)" "$SID"
ok "happy-new-registry-version" "$(reg_field "$NEWPID" version)" 2.0.0
LAST="$(tail -n 1 "$STATE/launches")"
has "happy-relaunch-resume" "$LAST" "--remote-control $R --resume $SID"
ok "happy-new-argv-resume" "$(tr '\0' ' ' < "/proc/$NEWPID/cmdline" 2>/dev/null | grep -c -- "--resume $SID")" 1
end_session

# count_in FILE PATTERN: matching lines in FILE, 0 when the file is absent.
count_in() { local n; n="$(grep -c -- "$2" "$1" 2>/dev/null)"; echo "${n:-0}"; }
# ghost_pane: idle pane whose prompt carries dim ghost text (an autosuggestion, not typed input).
ghost_pane() { idle_pane; awk '{ if ($0 == "❯ ") print "❯ \033[2mtry this\033[22m"; else print }' "$STATE/$S.pane" > "$STATE/$S.pane-e"; }

# ── 2. busy signals: each refuses with exit 1 and sends no keys ─────────────────────────────────────
echo "== busy signals"
reset_globals
echo busy > "$STATE/status"; start_session b1; rm -f "$STATE/status"
refused busy-registry busy "registry status 'busy'"
end_session
start_session b2; pane_with "✻ Thinking… (3s)" "" "$IDLE_FOOT"
refused busy-spinner busy "spinner above prompt"
end_session
start_session b3; pane_with "" "" "  esc to interrupt"
refused busy-footer busy "footer shows 'esc to interrupt'"
end_session
start_session b4; pane_with "" "" "$IDLE_FOOT"; pane_e_prompt "❯ hello"
refused busy-typed busy "typed input on the prompt"
end_session
end_session
reset_globals
echo "sleep 300" > "$STATE/child"; start_session b6; rm -f "$STATE/child"
refused busy-child busy "child process"
end_session
# a shell child stays busy even when its command line matches the allowlist ("mcp")
reset_globals
echo 'sleep 300; true # mcp' > "$STATE/child"; start_session b8; rm -f "$STATE/child"
refused busy-shell-child busy "child process"
has "busy-shell-child-argv0" "$OUT" "(bash)"
end_session
# an allowed MCP child (argv0 not a shell, cmdline matches the allowlist) stays idle
reset_globals
echo 'exec -a mcp-server sleep 300' > "$STATE/child"; start_session b9; rm -f "$STATE/child"
dry_ok allowed-mcp-child
end_session
reset_globals
start_session b7
refused busy-age busy "claude running only" CRSS_RESTART_MIN_AGE=600
end_session

# ── 3. idle judgments: ghost text is not typed input; an idle pane restarts ─────────────────────────
echo "== idle judgments"
reset_globals
start_session i1; ghost_pane; echo 2.0.0 > "$STATE/version"
mark_log
OUT="$(bash "$RS" "$S" 2>&1)"; RC=$?
ok "ghost-exit0" "$RC" 0
has "ghost-ok" "$OUT" "session-restart: $S: OK pid $OLD -> "
end_session

# ── 4. scheduled-tasks dialog: Escape, pin restored, session untouched, exit 4 ─────────────────────
echo "== scheduled-tasks dialog"
reset_globals
start_session d1; touch "$STATE/$S.tasks"
OUT="$(bash "$RS" "$S" 2>&1)"; RC=$?
ok "dialog-exit4" "$RC" 4
has "dialog-status" "$OUT" "session-restart: $S: SKIPPED(scheduled-tasks)"
ok "dialog-escape-sent" "$(count_in "$STATE/$S.events" escape)" 1
ok "dialog-pin-restored" "$(pin_now)" "<absent>"
ok "dialog-old-alive" "$([ -d "/proc/$OLD" ] && echo yes || echo no)" yes
end_session

# ── 5. exit-blocked: old pid survives /exit past the grace; pin restored; exit 3 ──────────────────────
echo "== exit-blocked"
reset_globals
start_session x1; touch "$STATE/$S.stuck"
OUT="$(bash "$RS" "$S" 2>&1)"; RC=$?
ok "exit-blocked-exit3" "$RC" 3
has "exit-blocked-status" "$OUT" "session-restart: $S: FAIL(exit-blocked)"
ok "exit-blocked-pin-restored" "$(pin_now)" "<absent>"
ok "exit-blocked-old-alive" "$([ -d "/proc/$OLD" ] && echo yes || echo no)" yes
end_session

# ── 6. timeout: no verified relaunch before WAIT; pin left so a later relaunch still resumes ─────────
echo "== timeout"
reset_globals
start_session t1; touch "$STATE/$S.stuck"
OUT="$(CRSS_RESTART_WAIT=3 CRSS_RESTART_EXIT_GRACE=60 bash "$RS" "$S" 2>&1)"; RC=$?
ok "timeout-exit3" "$RC" 3
has "timeout-status" "$OUT" "session-restart: $S: FAIL(timeout)"
ok "timeout-pin-left" "$(pin_now)" "$SID"
end_session

# ── 7. verify mismatches: version and sessionId each fail verification; exit 3 ──────────────────────
echo "== verify mismatches"
reset_globals
start_session v1
OUT="$(bash "$RS" "$S" --expect-version 9.9.9 2>&1)"; RC=$?
ok "verify-version-exit3" "$RC" 3
has "verify-version-status" "$OUT" "session-restart: $S: FAIL(verify) version 1.0.0 (want 9.9.9)"
end_session
reset_globals
start_session v2; OTHER="$(uuid)"; echo "$OTHER" > "$STATE/sid-override"
OUT="$(bash "$RS" "$S" 2>&1)"; RC=$?
ok "verify-sid-exit3" "$RC" 3
has "verify-sid-status" "$OUT" "session-restart: $S: FAIL(verify) sessionId $OTHER (want $SID)"
end_session
reset_globals
start_session v3; echo wrong-rc-name > "$STATE/rc-override"
OUT="$(bash "$RS" "$S" 2>&1)"; RC=$?
ok "verify-rc-exit3" "$RC" 3
has "verify-rc-status" "$OUT" "session-restart: $S: FAIL(verify) remote-control 'wrong-rc-name' (want '$R')"
end_session

# ── 8. refusals: each refuses with exit 1, sends no keys, and leaves pin and script unchanged ──────────
echo "== refusals"
reset_globals
OUT="$(bash "$RS" px-claude-remote 2>&1)"; RC=$?
ok "protected-exit1" "$RC" 1
has "protected-status" "$OUT" "REFUSED(protected)"
new_script np; sed -i '/^RESUME_PIN=/d' "$SC"
refused no-pin-loop no-pin-loop "resume pin"
rm -f "$SC"
new_script bk; sed -i '1a BACKEND=codex' "$SC"
refused backend backend "not supported"
rm -f "$SC"
new_script us; printf 'echo hi\n' > "$SC"
refused usage-shape usage-shape "no supervisor loop payload"
rm -f "$SC"
new_script nt
refused no-tmux no-tmux "does not exist"
rm -f "$SC"
start_session ns1; rm -f "$SC"
mark_log; NSPIN="$(pin_now)"
OUT="$(bash "$RS" "$S" --dry-run 2>&1)"; RC=$?
ok "no-start-script-exit1" "$RC" 1
has "no-start-script-status" "$OUT" "session-restart: $S: REFUSED(no-start-script)"
ok "no-start-script-no-keys" "$(sent_since)" 0
ok "no-start-script-pin-unchanged" "$(pin_now)" "$NSPIN"
NS_T0="$(date +%s)"
OUT="$(bash "$RS" "$S" --wait-idle --interval 0.2 --idle-polls 2 --max-wait 30 2>&1)"; RC=$?
NS_EL=$(( $(date +%s) - NS_T0 ))
ok "no-start-script-wait-exit1" "$RC" 1
has "no-start-script-wait-status" "$OUT" "session-restart: $S: REFUSED(no-start-script)"
hasnt "no-start-script-wait-not-deadline" "$OUT" "REFUSED(deadline)"
ok "no-start-script-wait-quick" "$([ "$NS_EL" -lt 15 ] && echo yes || echo no)" yes
ok "no-start-script-wait-no-keys" "$(sent_since)" 0
end_session
start_session fp1; printf '%s\n' "$(uuid)" > "$PIN"
refused foreign-pin foreign-pin "names"
end_session
start_session am1 "s/--remote-control/--zz --remote-control/"
refused argv-mismatch argv-mismatch ""
end_session
start_session vu1; mv "$STATE/version" "$STATE/version.off"
refused version-unknown version-unknown "--expect-version"
mv "$STATE/version.off" "$STATE/version"
end_session

# ── 9. dry-run, --if-outdated, exact "=" tmux targets ───────────────────────────────────────────────
echo "== dry-run, if-outdated, targets"
reset_globals
start_session r1
dry_ok dry
mark_log; bash "$RS" "$S" --dry-run >/dev/null 2>&1
ok "targets-no-bare-target" "$(tail -n +"$((MARK + 1))" "$STATE/tmux.log" | grep -cE -- '-t [^=]')" 0
ok "targets-exact-session-used" "$([ "$(tail -n +"$((MARK + 1))" "$STATE/tmux.log" | grep -c -- "-t =$S")" -gt 0 ] && echo yes || echo no)" yes
OUT="$(bash "$RS" "$S" --if-outdated 2>&1)"; RC=$?
ok "ifout-uptodate-exit0" "$RC" 0
has "ifout-uptodate-status" "$OUT" "session-restart: $S: UP-TO-DATE 1.0.0"
echo 2.0.0 > "$STATE/version"
OUT="$(bash "$RS" "$S" --if-outdated 2>&1)"; RC=$?
ok "ifout-outdated-exit0" "$RC" 0
has "ifout-outdated-status" "$OUT" "session-restart: $S: OK pid"
end_session

# ── 10. wait-idle: busy then idle restarts; a pane that stays busy hits the deadline ──────────────────
echo "== wait-idle"
reset_globals
start_session wi1; pane_with "✻ Thinking… (3s)" "" "$IDLE_FOOT"; cp "$STATE/$S.pane" "$T/busy.pane"
idle_pane; cp "$STATE/$S.pane" "$T/idle.pane"; cp "$T/busy.pane" "$STATE/$S.pane"
( sleep 1.5; cp "$T/idle.pane" "$STATE/$S.pane.new"; mv -f "$STATE/$S.pane.new" "$STATE/$S.pane" ) &
echo 2.0.0 > "$STATE/version"
OUT="$(bash "$RS" "$S" --wait-idle --interval 0.2 --idle-polls 2 --max-wait 30 2>&1)"; RC=$?
ok "waitidle-exit0" "$RC" 0
has "waitidle-waiting" "$OUT" "waiting: spinner above prompt"
has "waitidle-ok" "$OUT" "session-restart: $S: OK pid"
end_session
start_session wd1; pane_with "✻ Thinking… (3s)" "" "$IDLE_FOOT"
mark_log
OUT="$(bash "$RS" "$S" --wait-idle --interval 0.2 --idle-polls 2 --max-wait 2 2>&1)"; RC=$?
ok "deadline-exit1" "$RC" 1
has "deadline-status" "$OUT" "REFUSED(deadline)"
ok "deadline-no-keys" "$(sent_since)" 0
end_session

# gone: the tmux session disappears while --wait-idle is still waiting on a busy pane
reset_globals
start_session wg1; pane_with "✻ Thinking… (3s)" "" "$IDLE_FOOT"
mark_log; GONE_OUT="$T/gone.out"; GONE_RC="$T/gone.rc"; rm -f "$GONE_OUT" "$GONE_RC"
( bash "$RS" "$S" --wait-idle --interval 0.2 --idle-polls 2 --max-wait 30 > "$GONE_OUT" 2>&1; echo $? > "$GONE_RC" ) &
GONE_PID=$!
sleep 1
rm -f "$STATE/$S.panepid"   # the tmux stub's has-session reads this file: the session is gone
wait "$GONE_PID" 2>/dev/null
OUT="$(cat "$GONE_OUT" 2>/dev/null)"; RC="$(cat "$GONE_RC" 2>/dev/null)"
ok "gone-exit1" "$RC" 1
has "gone-status" "$OUT" "session-restart: $S: REFUSED(gone)"
ok "gone-no-keys" "$(sent_since)" 0
end_session

# ── 11. nudge: sent, failed (still exit 0), and --nudge-file body ───────────────────────────────────
echo "== nudge"
reset_globals
start_session n1; echo 2.0.0 > "$STATE/version"
OUT="$(CRSS_RESTART_NUDGE_DELAY=0 bash "$RS" "$S" --nudge 2>&1)"; RC=$?
ok "nudge-exit0" "$RC" 0
has "nudge-sent" "$OUT" "nudge=sent"
has "nudge-body" "$(cat "$STATE/session-send.log")" "Fleet maintenance"
echo 3.0.0 > "$STATE/version"; echo 1 > "$STATE/send-rc"
OUT="$(CRSS_RESTART_NUDGE_DELAY=0 bash "$RS" "$S" --nudge 2>&1)"; RC=$?
ok "nudge-failed-exit0" "$RC" 0
has "nudge-failed" "$OUT" "nudge=failed"
end_session
reset_globals
start_session nf1; printf 'custom nudge body\n' > "$T/nudge.txt"
OUT="$(CRSS_RESTART_NUDGE_DELAY=0 bash "$RS" "$S" --nudge-file "$T/nudge.txt" 2>&1)"; RC=$?
ok "nudge-file-exit0" "$RC" 0
has "nudge-file-body" "$(cat "$STATE/session-send.log")" "custom nudge body"
end_session

# ── 12. argument refusals (exit 2, before any tmux call) ────────────────────────────────────────────
echo "== argument refusals"
bash "$RS" zz-foo >/dev/null 2>&1; ok "unknown-prefix-exit2" "$?" 2
bash "$RS" 'px-a$b' >/dev/null 2>&1; ok "unsafe-name-exit2" "$?" 2
bash "$RS" px-x --nudge --nudge-file "$T/nudge.txt" >/dev/null 2>&1; ok "nudge-both-exit2" "$?" 2
bash "$RS" px-x --nudge-file "$T/missing.txt" >/dev/null 2>&1; ok "nudge-missing-exit2" "$?" 2
bash "$RS" px-x --interval 1 >/dev/null 2>&1; ok "tuning-without-wait-exit2" "$?" 2

finish test-session-restart
